import at.asitplus.attestation.*
import at.asitplus.testballoon.withData
import de.infix.testBalloon.framework.core.testSuite
import io.kotest.matchers.shouldBe
import io.kotest.matchers.types.shouldBeInstanceOf
import kotlin.time.Instant

val iosAssertionTests by testSuite {
    withData(
        CapturedIosData(
            Instant.parse("2026-02-23T17:32:00+01"),
            "9CYHJNG644",
            "at.asitplus.cryptotest.iosApp",
            true,
            "1gX/DwqNtQi02zjOvtsFOw==",
            "",
            "omlzaWduYXR1cmVYSDBGAiEAtdYEziuDlj3zWZbGZS7vuafTYvoCBEbmMJ5vLRgUGYwCIQDPXkcgyXyPzBD+sdPssE9yyOR+4/rv1wVrbvxx1YjgYnFhdXRoZW50aWNhdG9yRGF0YVglxO8o2ehg8OupYqV9SotBotDzcuUZogTLh5j3u6TBqY9AAAAAAQ==",
            0,
            true
        ),
        CapturedIosData(
            Instant.parse("2026-02-23T17:00:00+01"),
            "9CYHJNG644",
            "at.asitplus.cryptotest.iosApp",
            true,
            "ccAJFnG/XGvs9jCxk4u8aA==",
            "",
            "omlzaWduYXR1cmVYRzBFAiEArFO49ETCcve8DP5j7fd5Gq3blVoWryf8NOl7bmMqNB8CIGA+xXC5mWHi9y0K6WZTFjIWY0BOXEEQKUHIKmb4Aiy4cWF1dGhlbnRpY2F0b3JEYXRhWCXE7yjZ6GDw66lipX1Ki0Gi0PNy5RmiBMuHmPe7pMGpj0AAAAAB",
            0,
            false
        ),
        CapturedIosData(
            Instant.parse("2026-02-23T13:19:51.924Z"),
            "9CYHJNG644",
            "at.asitplus.cryptotest.iosApp",
            true,
            "1Q==",
            "",
            "omlzaWduYXR1cmVYRzBFAiEAgOTHKUM9dvAOEepdwefbSFZJeIVgPR6KvacnfeaBkroCID4aR8ZOpiE3InRLrzPdMGjxCa4W6DD6EdtAzIlTA3FGcWF1dGhlbnRpY2F0b3JEYXRhWCXE7yjZ6GDw66lipX1Ki0Gi0PNy5RmiBMuHmPe7pMGpj0AAAAAB",
            0,
            false
        )
    ) {
        val makoto = Makoto(
            iosAttestationConfiguration = IosAttestationConfiguration(
                IosAttestationConfiguration.AppData(
                    it.teamId,
                    it.bundleId,
                    it.sandbox
                )
            ),
            clock = FixedTimeClock(it.now)
        )

        val iosResult = makoto.ios.verifyAppAttestation(it.attestation, it.challenge)
        iosResult.shouldBeInstanceOf<AttestationResult.IOS.Verified>()
        makoto.ios.verifyAssertion(iosResult.attestation, it.assertion, it.challenge, 0).isSuccess shouldBe it.assertionOK
    }


}


data class CapturedIosData(
    val now: Instant,
    val teamId: String,
    val bundleId: String,
    val sandbox: Boolean,
    val challenge: ByteArray,
    val attestation: ByteArray,
    val assertion: ByteArray,
    val counter: Long,
    val assertionOK: Boolean,
) {
    constructor(
        now: Instant,
        teamId: String,
        bundleId: String,
        sandbox: Boolean,
        challenge: String,
        attestation: String,
        assertion: String,
        counter: Long,
        assertionOK: Boolean,
    ) : this(
        now, teamId, bundleId, sandbox,
        challenge.decodeBase64ToArray(), attestation.decodeBase64ToArray(), assertion.decodeBase64ToArray(),
        counter, assertionOK
    )
}
